import{_ as t,o,c as r,a2 as a}from"./chunks/framework.il0noOp3.js";const u=JSON.parse('{"title":"Decision record R2 — Power BI","description":"Decision record R2 — Power BI output is a PBIP project with a TMDL semantic model, not a .pbit over flat CSVs.","frontmatter":{"description":"Decision record R2 — Power BI output is a PBIP project with a TMDL semantic model, not a .pbit over flat CSVs."},"headers":[],"relativePath":"design/decisions/report-power-bi-project.md","filePath":"design/decisions/report-power-bi-project.md"}'),i={name:"design/decisions/report-power-bi-project.md"};function s(n,e,d,c,h,l){return o(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="decision-record-r2-—-power-bi" tabindex="-1">Decision record R2 — Power BI <a class="header-anchor" href="#decision-record-r2-—-power-bi" aria-label="Permalink to &quot;Decision record R2 — Power BI&quot;">​</a></h1><blockquote><p><strong>Status:</strong> Accepted 2026-08-02. Implementation landed; <strong>end-to-end verification is still open</strong> — see §5, which is the part of this record that matters most.</p><p><strong>Epic:</strong> AB#6450 · <strong>Feature:</strong> AB#6882 · <strong>Author:</strong> Claude Code</p></blockquote><h2 id="_1-decision" tabindex="-1">1. Decision <a class="header-anchor" href="#_1-decision" aria-label="Permalink to &quot;1. Decision&quot;">​</a></h2><p><strong>Emit a PBIP project — TMDL semantic model plus authored report pages — as the primary output. Keep the generated <code>.pbit</code> as a fallback only.</strong></p><h2 id="_2-why-the-previous-output-failed" tabindex="-1">2. Why the previous output failed <a class="header-anchor" href="#_2-why-the-previous-output-failed" aria-label="Permalink to &quot;2. Why the previous output failed&quot;">​</a></h2><p>Not opinion. Phase 0 measured it: <code>report.pbit</code> was <strong>4,689 bytes</strong>, of which the authored <code>Report/Layout</code> was <strong>2,190</strong>. Four flat CSVs, one lowercased <code>framework|area</code> text key joining everything, <strong>zero measures</strong>, no date dimension, and no report pages. Opening it presented a blank canvas and four tables.</p><p>The owner&#39;s verdict was &quot;a waste of my time&quot;, and that is the correct reading of the artefact: <strong>a model with no measures asks the reader to build the analysis the tool was supposed to do.</strong></p><h2 id="_3-why-pbip-rather-than-a-better-pbit" tabindex="-1">3. Why PBIP rather than a better <code>.pbit</code> <a class="header-anchor" href="#_3-why-pbip-rather-than-a-better-pbit" aria-label="Permalink to &quot;3. Why PBIP rather than a better `.pbit`&quot;">​</a></h2><p>Because PBIP is <strong>text</strong>. The semantic model is TMDL and the report is JSON, so both diff, both review in a pull request, and both can be regenerated by a later run without losing hand edits to parts this generator does not own. A <code>.pbit</code> is an opaque zip: improving it would have produced a better artefact that nobody could inspect, which is the same failure mode one layer up.</p><p>Concretely, the model now declares four real relationships onto framework, area and date dimensions instead of one shared string; eleven DAX measures; a calculated date dimension with a fact column that actually joins to it; and three authored report pages.</p><p>Lineage tags are <strong>derived from object names</strong>, not freshly generated. Random GUIDs would make every regenerated project a whole-file diff and would break report visuals that reference the previous tag — which would have quietly destroyed the reviewability that motivated the format.</p><h2 id="_4-four-defects-only-power-bi-desktop-could-find" tabindex="-1">4. Four defects only Power BI Desktop could find <a class="header-anchor" href="#_4-four-defects-only-power-bi-desktop-could-find" aria-label="Permalink to &quot;4. Four defects only Power BI Desktop could find&quot;">​</a></h2><p>Recorded because each cost real time and none is discoverable by reading the file:</p><ol><li><strong>Desktop validates every <code>$schema</code> URL against a regex</strong> before it opens anything, and rejects the whole project with <code>UnrecognizedSchemaVersion</code> on a mismatch. All three were wrong. They are genuinely inconsistent with each other — <code>pbip/pbipProperties</code>, <code>item/&lt;type&gt;/definitionProperties</code>, <code>gitIntegration/platformProperties</code> — and must not be tidied into a consistent-looking family.</li><li><strong>A TMDL <code>///</code> description precedes the object it documents</strong>, at that object&#39;s indent. Emitted as the first line <em>inside</em> a measure it fails with <code>Unexpected line type: Property!</code> pointing at the <strong>next</strong> line — sending you to inspect <code>formatString</code> when the fault is the line above.</li><li><strong><code>definition.pbir</code> version <code>1.0</code> means the classic report</strong> (a single <code>report.json</code>). The 4.x versions signal the enhanced report format, where the report is a <code>definition/pages/</code> tree. Declaring 4.x while shipping <code>report.json</code> tells Desktop to look for files that are not there.</li><li><strong>TMDL is indentation-sensitive and the indent character is a TAB.</strong> Converting the generator&#39;s here-strings to spaces produces a project Desktop refuses to open.</li></ol><h2 id="_5-what-is-verified-and-what-is-not-—-read-this-before-closing-anything" tabindex="-1">5. What is verified, and what is not — read this before closing anything <a class="header-anchor" href="#_5-what-is-verified-and-what-is-not-—-read-this-before-closing-anything" aria-label="Permalink to &quot;5. What is verified, and what is not — read this before closing anything&quot;">​</a></h2><p><strong>Verified.</strong> The TMDL parses under Microsoft&#39;s own parser — <code>Microsoft.PowerBI.Tabular.dll</code>&#39;s <code>TmdlSerializer.DeserializeDatabaseFromFolder</code> — returning 5 tables, 4 relationships and 11 measures. Power BI Desktop 2.156.951.0 opens the project: the title bar reads the project name and the model loads in Import mode with all five M queries and the <code>DataFolder</code> parameter present.</p><p><strong>Not verified.</strong> The report canvas does not yet render — Desktop&#39;s ribbon throws <code>Cannot read properties of undefined (reading &#39;customTheme&#39;)</code> because the generated <code>report.json</code> config declares no <code>themeCollection</code>. Until that is fixed and the pages are seen to render, clauses <code>B-01</code>–<code>B-05</code> are asserted against <strong>file shape</strong>, not against a working report.</p><p>That distinction is the whole point of <code>docs/design/report-conformance.md</code>. A generator whose output parses is not a generator whose output is usable, and 103 previously-closed report tickets are the evidence for treating that gap as real.</p><h2 id="_6-sources" tabindex="-1">6. Sources <a class="header-anchor" href="#_6-sources" aria-label="Permalink to &quot;6. Sources&quot;">​</a></h2><ul><li><a href="https://learn.microsoft.com/power-bi/developer/projects/projects-overview" target="_blank" rel="noreferrer">Power BI Desktop projects (PBIP)</a></li><li><a href="https://learn.microsoft.com/power-bi/developer/projects/projects-dataset" target="_blank" rel="noreferrer">Project semantic model folder</a> · <a href="https://learn.microsoft.com/power-bi/developer/projects/projects-report" target="_blank" rel="noreferrer">Project report folder</a></li><li><a href="https://learn.microsoft.com/power-bi/transform-model/desktop-tmdl-view" target="_blank" rel="noreferrer">TMDL view</a> · <a href="https://github.com/microsoft/json-schemas/tree/main/fabric" target="_blank" rel="noreferrer">JSON schemas repo</a></li></ul>',20)])])}const f=t(i,[["render",s]]);export{u as __pageData,f as default};
